Types.Decl:
type APICategory struct {
	ID    string `json:"id"`
	Slug  string `json:"slug"`
	Title string `json:"title"`
	// URL is the category's list on the site, null while the instance is on
	// no page; PostsURL its posts in the API.
	URL      *string `json:"url"`
	PostsURL string  `json:"posts_url"`
}

type APIPost struct {
	ID      string `json:"id"`
	Slug    string `json:"slug"`
	Title   string `json:"title"`
	Excerpt string `json:"excerpt"`
	// BodyHTML is the post's text as HTML (api.HTML); only the post's own
	// endpoint has it.
	BodyHTML string `json:"body_html,omitempty"`
	// Date is the post's date; UpdatedAt when its published revision was
	// saved.
	Date      time.Time `json:"date"`
	UpdatedAt time.Time `json:"updated_at"`
	// URL is the post's page, null while the instance is on no page;
	// APIURL the post in the API.
	URL        *string       `json:"url"`
	APIURL     string        `json:"api_url"`
	Image      *api.Image    `json:"image"`
	Categories []APICategory `json:"categories"`
}

type Category struct {
	ID    string
	Title string
	// URL is the category's list, empty like Post.URL.
	URL    string
	Active bool
}

type CategoryText struct {
	Slug  string `db:"slug"`
	Title string `db:"title"`
}

type DraftInput struct {
	// Locale is the language of the text, for example "nl".
	Locale string
	Title  string
	// Slug is derived from the title when empty (see content.Slug).
	Slug    string
	Excerpt string
	// Body is Markdown.
	Body string
	// ImageID is a media asset for the featured image.
	ImageID string
	// Date is the post's date; zero is today.
	Date time.Time
	// Author is the ID of the account the revision is credited to, empty for
	// none. Note describes the revision in the history, for example who sent
	// the text in.
	Author string
	Note   string
}

type ListView struct {
	Title string
	Posts []Post
	// Categories that have at least one visible post.
	Categories []Category
	// Category is set when the list is filtered.
	Category *Category
}

type Post struct {
	ID      string
	Title   string
	Excerpt string
	Body    template.HTML
	// Date is a calendar date (see frontend.Civil): {{date .Date}} shows the
	// same day in every site timezone.
	Date time.Time
	// URL is the post's page. Latest and the posts template function leave
	// it empty while the instance is on no page.
	URL string
	// ImageURL is the featured image as pages show it, at most media.ImageWidth
	// wide (see frontend.Frontend.Image); ImageSrcset lists smaller
	// copies for a srcset attribute, ImageWidth and ImageHeight are the
	// size of ImageURL and ImageOriginalURL is the uploaded file, for
	// downloads. All are empty when the post has no featured image.
	ImageURL         string
	ImageSrcset      string
	ImageOriginalURL string
	ImageWidth       int
	ImageHeight      int
	Categories       []Category
}

type PostFields struct {
	Date       time.Time   `db:"date"`
	Image      string      `db:"image_id,null"`
	Categories content.IDs `db:"category_ids"`
}

type PostText struct {
	Slug    string `db:"slug"`
	Title   string `db:"title"`
	Excerpt string `db:"excerpt"`
	Body    string `db:"body"`
}

type Service struct {
	// contains unexported fields
}
